-- G179 (2026-10-28): the subset of WhatsApp Desktop's ChatStorage.sqlite (the iOS app's Core Data schema) the reader
-- touches, as public forensic write-ups and open-source exporters describe it. Synthetic tests only; no real store.
CREATE TABLE ZWACHATSESSION (Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, ZCONTACTJID VARCHAR, ZPARTNERNAME VARCHAR,
  ZLASTMESSAGEDATE TIMESTAMP, ZSESSIONTYPE INTEGER, ZGROUPINFO INTEGER);
CREATE TABLE ZWAGROUPMEMBER (Z_PK INTEGER PRIMARY KEY, ZCHATSESSION INTEGER, ZMEMBERJID VARCHAR, ZCONTACTNAME VARCHAR,
  ZFIRSTNAME VARCHAR);
CREATE TABLE ZWAMESSAGE (Z_PK INTEGER PRIMARY KEY, ZCHATSESSION INTEGER, ZISFROMME INTEGER, ZMESSAGEDATE TIMESTAMP,
  ZSENTDATE TIMESTAMP, ZTEXT VARCHAR, ZMESSAGETYPE INTEGER, ZSTANZAID VARCHAR, ZGROUPMEMBER INTEGER, ZFROMJID VARCHAR,
  ZTOJID VARCHAR, ZMEDIAITEM INTEGER, ZFLAGS INTEGER);
CREATE TABLE ZWAMEDIAITEM (Z_PK INTEGER PRIMARY KEY, ZMESSAGE INTEGER, ZMETADATA BLOB, ZTITLE VARCHAR,
  ZMEDIALOCALPATH VARCHAR, ZFILESIZE INTEGER, ZVCARDSTRING VARCHAR);
